  'A global brief. Enter from any market, anywhere in the world.': 'Un briefing global. Puedes participar desde cualquier mercado del mundo.',
  'A goal everyone can aim for (optional)': 'Un objetivo al que todos pueden apuntar (opcional)',
  'A grey flame means the streak was lost. It shows your best run, and starts again from your next video.': 'Una llama gris significa que la racha se perdió. Muestra tu mejor racha y empieza de nuevo con tu próximo vídeo.',
  'A hidden talent or a fun fact about you': 'Un talento oculto o algo curioso sobre ti',
  'A hint under the question (optional)': 'Una pista bajo la pregunta (opcional)',
  'A ladder: 100k, 500k, 1M views and so on': 'Una escalera: 100k, 500k, 1M de visualizaciones y así',
  'A level, held against the goal itself all the way through.': 'Un nivel, comparado con la propia meta durante todo el periodo.',
  'A line under it': 'Una línea debajo',
  'A link for recruiting a creator straight into the VIP programme. It opens the usual sign-up, says they are joining the VIP creators, and makes them a VIP as they finish.': 'Un enlace para reclutar a un creador directamente en el programa VIP. Abre el registro de siempre, dice que se une a los creadores VIP y lo hace VIP al terminar.',
  'A link is the one thing this cannot be without.': 'El enlace es lo único de lo que esto no puede prescindir.',
  'A lit flame means you have posted in the last 7 days.': 'Una llama encendida significa que has publicado en los últimos 7 días.',
  'A map of every flight you have logged': 'Un mapa de todos los vuelos que has registrado',
  'A market is where the work happens: its own briefs, its own challenges, its own rooms. Everything social stays worldwide, so joining one never cuts you off from anybody.': 'Un mercado es donde ocurre el trabajo: sus propios briefs, sus propios retos, sus propias salas. Todo lo social sigue siendo global, así que unirte a uno nunca te aísla de nadie.',
  'A media kit you can send to a brand, share as a link, or download as a PDF. Every word on it is yours to change.': 'Un media kit que puedes enviar a una marca, compartir como enlace o descargar en PDF. Cada palabra es tuya para cambiarla.',
  'A message is how most things here actually start: a meet-up, a collab, a question about a brief.': 'Aquí casi todo empieza con un mensaje: una quedada, una colaboración, una duda sobre un brief.',
  'A milestone pays a VIP once, the month they reach it. Fill in as many rows as you like; each becomes its own bonus you can change later.': 'Un hito se paga una sola vez a cada VIP, el mes en que lo alcanza. Rellena tantas filas como quieras; cada una se convierte en un bonus que puedes cambiar después.',
  'A new best month': 'Un nuevo mejor mes',
  'A new country or region with its own rooms, challenges, leads and members. Creators living there can join it.': 'Un nuevo país o región con sus propias salas, retos, responsables y miembros. Los creadores que viven allí pueden unirse.',
  'A new VIP, day one': 'Un VIP nuevo, el primer día',
  'A new VIP\'s first day in {m}': 'El primer día de un nuevo VIP en {m}',
  'A note for you. Applicants never see it - it is suggested when you approve them, and you can change it then.': 'Una nota para ti. Los solicitantes nunca la ven: se sugiere cuando los apruebas y puedes cambiarla entonces.',
  'A nudge before a live challenge closes, so you can get your entries in.': 'Un aviso antes de que se cierre un reto en marcha, para que te dé tiempo a participar.',
  'A number': 'Un número',
  'A one-off for reaching a total, such as 1M views': 'Un pago único por alcanzar un total, como 1 M de visualizaciones',
  'A past admin': 'Un administrador anterior',
  'A percentage': 'Un porcentaje',
  'a photo': 'una foto',
  'A photo from the trip': 'Una foto del viaje',
  'A photo just for your portfolio cover.': 'Una foto solo para la portada de tu portafolio.',
  'A photo, or a screenshot from Apple Wallet': 'Una foto o una captura de Apple Wallet',
  'A picture, ready for a story.': 'Una imagen, lista para una historia.',
  'A pinned video stays first whatever the sort or the filter, and never retires.': 'Un vídeo fijado se queda el primero sea cual sea el orden o el filtro, y nunca se retira.',
  'A point per video capped at ten, plus 5k / 10k / 50k view milestones.': 'Un punto por vídeo con un máximo de diez, más los hitos de 5k / 10k / 50k visualizaciones.',
  'A project you\'re working on, a question for the community, something you\'re proud of.': 'Un proyecto en el que estás trabajando, una pregunta para la comunidad, algo de lo que estés orgulloso.',
  'A quick check on how getting paid and using vouchers went for you.': 'Una pregunta rápida sobre cómo te fue con los pagos y los vales.',
  'A reminder on the Members list when the date comes round. Optional.': 'Un aviso en la lista de miembros cuando llegue la fecha. Opcional.',
  'A running total': 'Un total acumulado',
  'A sentence or two, please.': 'Una o dos frases, por favor.',
  'A short walk through the platform, pointing at where everything is. Takes about two minutes and you can stop at any point.': 'Un recorrido rápido por la plataforma que te enseña dónde está cada cosa. Dura unos dos minutos y puedes pararlo cuando quieras.',
  'A statement already counted this month. Ask the team to take it out.': 'Un extracto ya contó este mes. Pide al equipo que lo quite.',
  'A theme, a brief, hook ideas and a goal for each month. Every VIP in scope is told, sees it at the top of their month, and gets live standings.': 'Un tema, un briefing, ideas de gancho y un objetivo para cada mes. Todos los VIP incluidos reciben un aviso, lo ven arriba de su mes y tienen una clasificación en directo.',
  'A travel quote you live by…': 'Una frase sobre viajar con la que te identifiques…',
  'A Tryp.com voucher': 'Un vale de Tryp.com',
  'A video could not be read': 'No se pudo leer un vídeo',
  'A video counts if it is public, posted on your own account during the month it is counted for, and mentions or tags Tryp.com as agreed with the team. Reposts of an earlier video do not count.': 'Un vídeo cuenta si es público, está publicado en tu propia cuenta durante el mes en que se cuenta y menciona o etiqueta a Tryp.com como se haya acordado con el equipo. Las republicaciones de un vídeo anterior no cuentan.',
  'A video counts if it is public, posted on your own account within the last {days} days, and mentions or tags Tryp.com as agreed with the team. Reposts of an earlier video do not count.': 'Un vídeo cuenta si es público, está publicado en tu propia cuenta en los últimos {days} días y menciona o etiqueta a Tryp.com como se acordó con el equipo. Las republicaciones de un vídeo anterior no cuentan.',
  'A video earns for this many days': 'Un vídeo genera ingresos durante tantos días',
  'A video that passes several milestones scores every one of them.': 'Un vídeo que supera varios hitos puntúa por todos ellos.',
  'A video was disqualified this month': 'Se descalificó un vídeo este mes',
