  'A VIP who signs up with the link starts here, until they are approved into a market. Then they move to that market\'s programme on their own.': 'Un VIP que se registra con el enlace empieza aquí hasta que lo aprueban en un mercado. Después pasa solo al programa de ese mercado.',
  'A voucher reward is created when the statement is approved. You issue the code from Rewards, as with any voucher.': 'Se crea una recompensa de vale cuando se aprueba el extracto. Emites el código desde Recompensas, como con cualquier vale.',
