  'Approve all {n}': 'Aprobar los {n}',
  'Approve all {n} drafts? Each one is added to the creator\'s balance, and their payout window opens.': '¿Aprobar los {n} borradores? Cada uno se suma al saldo del creador y se abre su plazo de cobro.',
  'Approve all {n} drafts? Each one raises its invoice for the creator. You can still stop an invoice from Rewards.': '¿Aprobar los {n} borradores? Cada uno genera la factura del creador. Aún puedes detener una factura desde Recompensas.',
  'Approved': 'Aprobados',
  'Approved, to pay': 'Aprobada, por pagar',
  'Approving a month adds it to each balance. For {d} days after the month ends, a VIP can take cash (from {a}) or a Tryp.com voucher (any amount). Otherwise it keeps growing.': 'Al aprobar un mes se suma a cada saldo. Durante {d} días tras el cierre del mes, un VIP puede cobrar en efectivo (desde {a}) o pedir un bono de Tryp.com (cualquier importe). Si no, el saldo sigue creciendo.',
  'Approving a statement adds it to the creator\'s balance and opens their payout window: cash once the balance reaches the threshold, or a Tryp.com voucher for any amount. Their invoice is raised when they ask for cash. Late corrections go on next month\'s statement or as a balance correction in Balances.': 'Al aprobar un extracto se suma al saldo del creador y se abre su plazo de cobro: efectivo cuando el saldo llega al mínimo, o un bono de Tryp.com por cualquier importe. La factura se genera cuando pide el efectivo. Las correcciones tardías van en el extracto del mes siguiente o como corrección de saldo en Saldos.',
  'Approving a statement raises the creator\'s invoice and counts as approving it. A creator with no payment details is approved anyway and their invoice follows the day they save them. Late corrections go on next month\'s statement, never by reopening a month that is paid.': 'Aprobar un extracto genera la factura del creador y cuenta como aprobarla. Un creador sin datos de pago se aprueba igualmente y su factura llega el día que los guarde. Las correcciones tardías van en el extracto del mes siguiente, nunca reabriendo un mes pagado.',
