  'At the end of each month we take a final reading of your views, draft your statement and, once it is approved, your invoice.': 'Al final de cada mes hacemos una lectura final de tus visualizaciones, preparamos tu extracto y, una vez aprobado, tu factura.',
  'At the end of each month we take a final reading of your views, draft your statement and, once it is approved, your invoice. Small amounts below the minimum payout carry over to the next month.': 'Al final de cada mes hacemos una lectura final de tus visualizaciones, redactamos tu extracto y, una vez aprobado, tu factura. Las cantidades pequeñas por debajo del pago mínimo pasan al mes siguiente.',
