  'Bonuses': 'Bonus',
  'Bonuses are rules, not hand payments. The month-end close works each one out for every VIP, and you check the result before anything is approved. You can set bonuses for each creator, for the ranking in this market, or for the ranking across every VIP.': 'Los bonus son reglas, no pagos a mano. El cierre de fin de mes calcula cada uno para cada VIP y tú revisas el resultado antes de aprobar nada. Puedes fijar bonus para cada creador, para la clasificación de este mercado o para la clasificación de todos los VIP.',
  'Bonuses running now': 'Bonificaciones activas',
  'Booking both in one trip usually comes out cheaper than booking them separately. Show the total per person.': 'Reservar los dos en un mismo viaje suele salir más barato que por separado. Muestra el total por persona.',
