  'Challenge': 'Reto',
  'Challenge briefs and rules are translated automatically the first time a creator reads them in this language. Check them here, and correct anything that reads wrong. Your version is kept and shown instead.': 'Los briefings y las reglas de los retos se traducen automáticamente la primera vez que un creador los lee en este idioma. Revísalos aquí y corrige lo que suene mal. Se guarda tu versión y se muestra en su lugar.',
  'Challenge closed': 'Reto cerrado',
  'Challenge deadline reminders': 'Recordatorios de cierre de retos',
  'Challenge deadlines land here on their own, and so do your flights. Anything else is a date somebody has to put in, and there is a box at the foot of this page for asking.': 'Las fechas límite de los retos aparecen aquí solas, y tus vuelos también. Cualquier otra cosa es una fecha que alguien tiene que meter, y al final de esta página hay un recuadro para pedirlo.',
