  'I have read the VIP terms and I agree to them.': 'He leído los términos VIP y los acepto.',
  'I have turned them on': 'Ya las he activado',
  'I have turned them on - check again': 'Ya las he activado, comprueba otra vez',
  'I just earned': 'Acabo de conseguir',
  'I make': 'Hago',
  'I make short travel videos about the places I go and the things worth stopping for. I am part of the Tryp.com Content Creator Community, where creators from around the world make work for monthly challenges.': 'Hago vídeos cortos de viajes sobre los sitios a los que voy y lo que merece la pena. Formo parte de la Tryp.com Content Creator Community, donde creadores de todo el mundo crean contenido para retos mensuales.',
  'I\'ll do this later': 'Lo haré más tarde',
  'I\'m in Lisbon the same week. Fancy shooting a couple of reels around Alfama, or just a coffee?': 'Estoy en Lisboa esa misma semana. ¿Te apetece grabar un par de reels por Alfama, o un café?',
  'I\'m planning a Balkans road trip next spring and would love to team up with anyone heading that way.': 'Estoy planeando una ruta en coche por los Balcanes la próxima primavera y me encantaría unirme a quien vaya hacia allí.',
  'Icon': 'Icono',
  'Identity': 'Identidad',
  'If an account exists for {email}, you\'ll receive a reset link shortly. Check your spam folder too.': 'Si existe una cuenta para {email}, recibirás enseguida un enlace para restablecer la contraseña. Mira también en la carpeta de spam.',
  'If it keeps failing, please let us know rather than waiting.': 'Si sigue fallando, avísanos en lugar de esperar.',
  'If it still will not read, try the digital pass instead: a screenshot straight from Apple Wallet or the airline app scans far more reliably than a photo of a printed one. Otherwise close this and type the flight in.': 'Si sigue sin leerse, prueba con la tarjeta digital: una captura directa de Apple Wallet o de la app de la aerolínea se escanea mucho mejor que una foto de una impresa. Si no, cierra esto y escribe el vuelo a mano.',
  'If the month ended now: {n} would earn it, {a} in all.': 'Si el mes terminara ahora: lo ganarían {n}, {a} en total.',
  'If you win before we have these, your prize waits until we do. You can add them any time from Settings.': 'Si ganas antes de que los tengamos, tu premio espera hasta entonces. Puedes añadirlos cuando quieras desde Ajustes.',
  'If your streak is at risk, we’ll nudge you around 6pm to play before midnight.': 'Si tu racha está en peligro, te avisamos sobre las 18:00 para que juegues antes de medianoche.',
