  'It appears for everyone who entered, once the challenge has ended - never while it is running.': 'Aparece a todos los que participaron cuando el reto ha terminado, nunca mientras está en curso.',
  'It behaves like': 'Se comporta como',
  'It builds up through the period, so being halfway to the goal halfway through is on track.': 'Se acumula a lo largo del periodo, así que estar a mitad de la meta a mitad de periodo va según lo previsto.',
  'It cannot end before it starts.': 'No puede terminar antes de empezar.',
  'It goes out of the tracker along with the hook and any notes on it. A synced video comes back on the next sync; one added by hand does not.': 'Sale del seguimiento junto con el gancho y cualquier nota que tenga. Un vídeo sincronizado vuelve en la siguiente sincronización; uno añadido a mano, no.',
  'It is a level, not a total, so it is held against the goal itself all the way through.': 'Es un nivel, no un total, así que se compara con la meta durante todo el periodo.',
