  'On the last day of each month we take a final reading of your views. Your statement appears here once the team has checked it, and your invoice follows.': 'El último día de cada mes hacemos una lectura final de tus visualizaciones. Tu extracto aparece aquí cuando el equipo lo ha revisado, y después llega tu factura.',
