  'One goal comes from {q}': 'Un objetivo viene de {q}',
  'One goal here is {q}\'s goal shared across its months, rising gently as the quarter goes on.': 'Una de las metas de aquí es la meta de {q} repartida entre sus meses, subiendo poco a poco a lo largo del trimestre.',
  'One goal here is the monthly goals added together. Set a quarter goal to replace it.': 'Una de las metas de aquí es la suma de las metas mensuales. Fija una meta trimestral para sustituirla.',
  'One goal is the months added up': 'Un objetivo es la suma de los meses',
  'One line per creator per month: name, month, views, and optionally the amount and the rate. Paste straight from a spreadsheet.': 'Una línea por creador y mes: nombre, mes, visualizaciones y, si quieres, el importe y la tarifa. Pégalo directamente desde una hoja de cálculo.',
  'One line under the title': 'Una línea bajo el título',
  'One line, shown under the market name.': 'Una línea, mostrada bajo el nombre del mercado.',
  'One link for every VIP, in every market, and it never expires. They sign up as usual, are marked as VIPs in the applications list, and are placed with their own market\'s VIP programme when you approve them.': 'Un enlace para todos los VIP, en todos los mercados, y no caduca nunca. Se registran como siempre, aparecen marcados como VIP en la lista de solicitudes y se colocan en el programa VIP de su mercado cuando los apruebas.',
  'One link for every VIP, in every market. They sign up as usual, are marked as VIPs in the applications list, and are placed with their own market\'s VIP programme when you approve them.': 'Un único enlace para todos los VIP, en todos los mercados. Se registran como siempre, aparecen marcados como VIP en la lista de solicitudes y, cuando los apruebas, pasan al programa VIP de su propio mercado.',
