  'Only VIP creators and the team can see these. Ask anything, share what is working, and meet the other VIPs.': 'Solo los creadores VIP y el equipo pueden verlas. Pregunta lo que quieras, comparte lo que funciona y conoce a los demás VIP.',
  'Only VIP creators and the team can see these. This is where the WhatsApp group lives now.': 'Solo los creadores VIP y el equipo pueden verlas. Aquí vive ahora el grupo de WhatsApp.',
