  'We do not recognise that VIP link. Check you copied all of it, or ask the team to send it again. You can still sign up as a creator below.': 'No reconocemos ese enlace VIP. Comprueba que lo has copiado entero o pide al equipo que te lo envíe de nuevo. Aún puedes registrarte como creador abajo.',
  'We email a reset link to the address above.': 'Te enviamos un enlace para cambiarla a la dirección de arriba.',
