  'We filled in what your profile already says. Change anything, skip anything, and your card is ready.': 'Hemos rellenado lo que ya dice tu perfil. Cambia o salta lo que quieras y tu tarjeta estará lista.',
  'We have sent you a confirmation link. Open it, then log in and we will take you through the rest.': 'Te hemos enviado un enlace de confirmación. Ábrelo, inicia sesión y te guiaremos en el resto.',
  'We have your age as {n}. Add your date of birth and it will stay right on your birthday.': 'Tenemos tu edad como {n}. Añade tu fecha de nacimiento y se mantendrá correcta cada cumpleaños.',
  'We match them by themselves. Its views count once, and you both get the points.': 'Los emparejamos automáticamente. Sus visualizaciones cuentan una vez y los dos recibís los puntos.',
  'We post new positions here first. Keep creating great content and you\'ll be top of mind.': 'Publicamos las vacantes nuevas aquí primero. Sigue creando buen contenido y te tendremos presente.',
  'We want your ideas for challenges, features and anything else.': 'Queremos tus ideas para retos, funciones y lo que sea.',
