  'You are in an app\'s built-in browser, which cannot add anything to your home screen. Open Tryp.com in Safari or Chrome and this will take ten seconds.': 'Estás en el navegador interno de otra app, que no puede añadir nada a la pantalla de inicio. Abre Tryp.com en Safari o Chrome y esto te llevará diez segundos.',
  'You are in the prize places, so this one goes to someone else.': 'Estás en los puestos con premio, así que este va para otra persona.',
  'You are in the worldwide community as well. A market is where your briefs come from, not a smaller room you go into instead.': 'También estás en la comunidad global. Un mercado es de donde vienen tus briefs, no una sala más pequeña a la que te metes en su lugar.',
  'You are in these.': 'Estás en estos.',
  'You are joining the Tryp.com Content Creator Community, a global community of travel creators who make great content, compete in challenges and earn real rewards.': 'Te estás uniendo a la Comunidad de Creadores de Contenido de Tryp.com, una comunidad global de creadores de viajes que hacen buen contenido, compiten en retos y ganan recompensas de verdad.',
  'You are joining the VIP creators': 'Te unes a los creadores VIP',
  'You are left out of the public map, the creators strip and the wall of fame. Fellow creators can still find you in the app.': 'Quedas fuera del mapa público, la franja de creadores y el muro de honor. Los demás creadores pueden seguir encontrándote en la app.',
  'You are looking at {p}. You can see everything here, but only its own lead can change it.': 'Estás viendo {p}. Puedes ver todo, pero solo su responsable puede cambiarlo.',
  'You are looking at this the way the creator sees it. Nothing here can be edited by you.': 'Lo estás viendo tal como lo ve el creador. No puedes editar nada desde aquí.',
  'You are not on the board yet. Play any travel game today and you will be tomorrow.': 'Todavía no estás en la lista. Juega hoy a cualquier juego de viajes y mañana estarás.',
  'You are paid by the views your videos bring. Add your first video to start your month.': 'Cobras por las visualizaciones que traen tus vídeos. Añade tu primer vídeo para empezar tu mes.',
  'You are paid for the views your videos gain during each calendar month, at the rate on your VIP page. Views from before you added a video, or from before the month began, are not counted.': 'Se te paga por las visualizaciones que ganan tus vídeos durante cada mes natural, a la tarifa de tu página VIP. No se cuentan las visualizaciones de antes de añadir un vídeo ni de antes de que empezara el mes.',
  'You are reading this the way the creator sees it. Only they can change what it says.': 'Estás leyendo esto tal y como lo ve el creador. Solo esa persona puede cambiar lo que pone.',
  'You are signed in as': 'Has iniciado sesión como',
